// Browser test of the Update page: the "Online update" card and the upload
// in pieces.
// Serves the page generated by the firmware (DUMP=1 ./run.sh TOKEN writes
// update_online.html) together with a mock of the firmware's endpoints
// (/update/check, /update/install, /update/state, POST /update) and drives it
// in Chromium.
// Needs Node.js and Playwright (npm install playwright; npx playwright install chromium).
// Run: DUMP=1 ./run.sh TOKEN && node web_test.js
const http = require('http'); const fs = require('fs'); const path = require('path');
const { chromium } = require('playwright');
const page = fs.readFileSync(path.join(__dirname, 'update_online.html'), 'utf8');
let scenario = 'available', stateCalls = 0, installs = 0;
let pieces = [], failPiece = -1, barAtPiece = [];
const srv = http.createServer((req, res) => {
  const json = o => { res.writeHead(200, {'Content-Type': 'application/json'}); res.end(JSON.stringify(o)); };
  if (req.url === '/update') { res.writeHead(200, {'Content-Type': 'text/html'}); return res.end(page); }
  if (req.url === '/') { res.writeHead(200, {'Content-Type': 'text/html'}); return res.end('<p id=status>status page</p>'); }
  if (req.url === '/update/check') {
    if (scenario === 'uptodate') return json({ok: true, current: 'v1.2.0', latest: 'v1.2.0', upToDate: true});
    if (scenario === 'none') return json({ok: false, current: 'unknown', message: 'No release has been published yet.'});
    if (scenario === 'fail') return json({ok: true, current: 'unknown', latest: 'v1.2.1', upToDate: false});
    return json({ok: true, current: 'unknown', latest: 'v1.2.0<img src=x onerror=alert(1)>', published: '2026-11-03T20:05:00Z',
                 notes: 'https://github.com/Modac/twitchDisplay/releases/tag/v1.2.0', upToDate: false});
  }
  if (req.url === '/update/install' && req.method === 'POST') { installs++; return json({ok: true, message: 'Installing v1.2.0.'}); }
  if (req.url.startsWith('/update?') && req.method === 'POST') {   // one piece of the upload
    const q = new URL(req.url, 'http://x').searchParams;
    let len = 0;
    req.on('data', d => { len += d.length; });
    req.on('end', () => {
      const off = +q.get('offset'), total = +q.get('total');
      pieces.push({off, total, len});
      if (pieces.length - 1 === failPiece) { res.writeHead(400, {'Content-Type': 'application/json'}); return res.end(JSON.stringify({ok: false, message: 'Update failed: Upload out of order, start again.'})); }
      const end = Math.min(off + 65536, total);
      json(end < total ? {ok: true, message: 'Received ' + end + ' bytes.'} : {ok: true, message: 'Update successful, the display restarts now.'});
    });
    return;
  }
  if (req.url === '/update/state') {
    stateCalls++;
    if (scenario === 'fail') return json({state: 'failed', message: 'Download timed out.'});
    if (stateCalls < 2) { req.socket.destroy(); return; }   // display busy installing / restarting
    return json({state: 'idle', version: 'v1.2.0'});
  }
  res.writeHead(404); res.end();
});
srv.listen(0, async () => {
  const base = 'http://127.0.0.1:' + srv.address().port;
  const b = await chromium.launch(); const p = await b.newPage({viewport: {width: 390, height: 844}});
  let alerts = 0; p.on('dialog', d => { alerts++; d.dismiss(); });
  const ok = (c, m) => { console.log((c ? 'PASS ' : 'FAIL ') + m); if (!c) process.exitCode = 1; };

  await p.goto(base + '/update'); await p.click('#check');
  await p.waitForSelector('#online button');
  ok((await p.textContent('#online')).includes('is available (released 2026-11-03)'), 'shows the available version and date');
  ok(await p.$('#online img') === null && alerts === 0, 'release data is inserted as text (no HTML injection)');
  ok(await p.getAttribute('#online a', 'href') === 'https://github.com/Modac/twitchDisplay/releases/tag/v1.2.0', 'release notes link');
  await p.click('#online button');
  await p.waitForURL(base + '/', {timeout: 20000});
  ok(installs === 1 && stateCalls >= 2, 'install posted, waited through the restart, then opened the status page');

  scenario = 'uptodate'; await p.goto(base + '/update'); await p.click('#check');
  await p.waitForFunction(() => document.getElementById('online').textContent.includes('newest'));
  ok((await p.textContent('#online')).includes('You have the newest version (v1.2.0).'), 'up to date message');

  scenario = 'none'; await p.goto(base + '/update'); await p.click('#check');
  await p.waitForSelector('#online .err');
  ok((await p.textContent('#online .err')) === 'No release has been published yet.', 'error from the display is shown');

  scenario = 'fail'; await p.goto(base + '/update'); await p.click('#check');
  await p.waitForSelector('#online button'); await p.click('#online button');
  await p.waitForSelector('#online .err', {timeout: 20000});
  ok((await p.textContent('#online .err')) === 'Update failed: Download timed out.', 'failed install is reported, the page stays');
  ok(!(await p.isDisabled('#check')), 'check button usable again');

  // upload in pieces: 200000 bytes = 3 pieces of 64 KB + 3392 bytes
  const fw = path.join(__dirname, 'build', 'upload_test.bin');
  fs.writeFileSync(fw, Buffer.alloc(200000, 0xE9));
  await p.goto(base + '/update');
  await p.setInputFiles('#file', fw);
  await p.click('#go');
  await p.waitForFunction(() => document.getElementById('msg').className === 'ok', null, {timeout: 20000});
  ok(JSON.stringify(pieces.map(x => x.off)) === '[0,65536,131072,196608]' && pieces.every(x => x.total === 200000),
     'file sent in 64 KB pieces, in order, with the total size');
  ok(pieces.every((x, i) => x.len > (i < 3 ? 65536 : 3392)), 'each piece carries its part of the file');
  ok(await p.getAttribute('#bar', 'value') === '100' && (await p.textContent('#msg')).startsWith('Update successful'), 'bar full, success shown');

  pieces = []; failPiece = 1;
  await p.goto(base + '/update');
  await p.setInputFiles('#file', fw);
  await p.click('#go');
  await p.waitForSelector('#msg.err', {timeout: 20000});
  ok(pieces.length === 2 && (await p.textContent('#msg')) === 'Update failed: Upload out of order, start again.', 'stops at a failed piece and shows the error');
  ok(!(await p.isDisabled('#go')) && +(await p.getAttribute('#bar', 'value')) < 50, 'upload button usable again, bar not full');
  await b.close(); srv.close();
});
